import java.util.*;
sealed interface Command permits Add,Reset{} record Add(int value)implements Command{} record Reset()implements Command{}
public class Main {static int apply(int start,Command c){return switch(c){case Add(int value)->start+value;case Reset()->0;};}public static void main(String[] args){Scanner s=new Scanner(System.in);int start=s.nextInt();String op=s.next();Command c=op.equals("add")?new Add(s.nextInt()):new Reset();System.out.println(apply(start,c));}}

