import java.util.*;
sealed interface Expr permits Num,Add{} record Num(int value)implements Expr{} record Add(Expr left,Expr right)implements Expr{}
public class Main {static int eval(Expr e){return switch(e){case Num(int value)->value;case Add(Expr left,Expr right)->eval(left)+eval(right);};}public static void main(String[] args){Scanner s=new Scanner(System.in);Expr e=new Add(new Add(new Num(s.nextInt()),new Num(s.nextInt())),new Num(s.nextInt()));System.out.println(eval(e));}}

