import java.lang.annotation.*;import java.lang.reflect.*;import java.util.*;
@Retention(RetentionPolicy.RUNTIME)@Target(ElementType.METHOD)@interface Command{String value();} class Handler{@Command("create")void add(){}@Command("list")void show(){}void helper(){}}
public class Main {public static void main(String[] args){Arrays.stream(Handler.class.getDeclaredMethods()).sorted(Comparator.comparing(Method::getName)).filter(m->m.isAnnotationPresent(Command.class)).forEach(m->System.out.println(m.getAnnotation(Command.class).value()+"->"+m.getName()));}}

