import java.lang.annotation.*;import java.lang.reflect.*;import java.util.*;
@Retention(RetentionPolicy.RUNTIME)@Target(ElementType.RECORD_COMPONENT)@interface Range{int min();int max();}record User(@Range(min=0,max=150) int age){}
public class Main {public static void main(String[] args)throws Exception{User u=new User(new Scanner(System.in).nextInt());Range r=User.class.getRecordComponents()[0].getAnnotation(Range.class);System.out.println(u.age()>=r.min()&&u.age()<=r.max()?"valid":"invalid");}}

